// ?updateAnimateWindow@ProcessAnimateWindowSlideFromLeft@@UAE_NPAVAnimateWindow@@@Z
// partial score=0.95 date=2026-09-07
// cl: /DNDEBUG /MD /EHsc
// Readable body of ?updateAnimateWindow@ProcessAnimateWindowSlideFromLeft@@UAE_NPAVAnimateWindow@@@Z.
// Retail 0x00495CC0, 230 bytes. The window slides in from the left: advance
// curPos.x by vel.x, finish when it passes endPos.x, otherwise ease vel.x by
// m_slowDownRatio near the end and clamp it from below at 1.0f.
// getVel is an sret call (ILT 0x0000E548); time is _bfme_timeGetTime@0;
// winSetPosition goes through ILT 0x0001949D; the 1.0f clamp reads the
// shared retail float g_bfmeDefaultBU (verified 1.0f in the binary).
// The finish path has no curPos.x snap and no winSetPosition call, unlike ZH.
// Near miss: every instruction matches but MSVC7.1 homes the endPos struct
// (8B) where retail spills only endPos.y (4B) into vel's home, so the frame
// is sub esp,0x18 against retail's 0x10. Scalar endPos getters give the 0x10
// frame but drop the dead endPos.y load+spill; struct copy-init keeps the
// load+spill but costs the home. Tried: decl order both ways, const endPos,
// const/scalar/out-of-class getters, scoped endPos lifetime, /EHsc on/off,
// /Os. The remaining lever is how to keep the dead .y spill without a home.

typedef unsigned int UnsignedInt;
typedef int Int;
typedef float Real;
typedef bool Bool;

struct ICoord2D
{
	Int x;
	Int y;
};

struct Coord2D
{
	Real x;
	Real y;
	Coord2D(void) {}
	Coord2D(const Coord2D &that) : x(that.x), y(that.y) {}
	~Coord2D(void) {}
};

class GameWindow
{
public:
	Int winSetPosition(Int x, Int y);
};

class AnimateWindow
{
public:
	virtual void unused(void) = 0;

	UnsignedInt getStartTime(void) { return m_startTime; }
	GameWindow *getGameWindow(void) { return m_gameWindow; }
	ICoord2D getCurPos(void) { return m_curPos; }
	ICoord2D getEndPos(void) { return m_endPos; }
	Coord2D getVel(void);
	Bool isFinished(void) { return m_finished; }
	void setFinished(Bool finished) { m_finished = finished; }
	void setCurPos(ICoord2D pos) { m_curPos = pos; }
	void setVel(Coord2D vel) { m_vel = vel; }

private:
	UnsignedInt m_delay;
	ICoord2D m_startPos;
	ICoord2D m_endPos;
	ICoord2D m_curPos;
	ICoord2D m_restPos;
	GameWindow *m_gameWindow;
	Coord2D m_vel;
	UnsignedInt m_startTime;
	UnsignedInt m_endTime;
	unsigned char m_padding[5];
	Bool m_finished;
};

class ProcessAnimateWindowSlideFromLeft
{
public:
	virtual ~ProcessAnimateWindowSlideFromLeft();
	virtual void initAnimateWindow(AnimateWindow *);
	virtual void initReverseAnimateWindow(AnimateWindow *, UnsignedInt);
	virtual Bool updateAnimateWindow(AnimateWindow *);
	virtual Bool reverseAnimateWindow(AnimateWindow *);

private:
	Coord2D m_maxVel;
	Int m_slowDownThreshold;
	Real m_slowDownRatio;
	Real m_speedUpRatio;
};

extern "C" UnsignedInt __stdcall bfme_timeGetTime(void);
extern float g_bfmeDefaultBU;

// ?updateAnimateWindow@ProcessAnimateWindowSlideFromLeft@@UAE_NPAVAnimateWindow@@@Z
Bool ProcessAnimateWindowSlideFromLeft::updateAnimateWindow(AnimateWindow *animWin)
{
	if (!animWin)
		return true;

	if (animWin->isFinished())
		return true;

	if (bfme_timeGetTime() < animWin->getStartTime())
		return false;

	GameWindow *win = animWin->getGameWindow();
	if (!win)
		return true;

	ICoord2D curPos = animWin->getCurPos();
	ICoord2D endPos = animWin->getEndPos();
	Coord2D vel = animWin->getVel();
	curPos.x += (Int)vel.x;

	if (curPos.x > endPos.x)
	{
		animWin->setFinished(true);
		return true;
	}
	win->winSetPosition(curPos.x, curPos.y);
	animWin->setCurPos(curPos);
	if (endPos.x - curPos.x <= m_slowDownThreshold)
		vel.x *= m_slowDownRatio;
	if (vel.x < g_bfmeDefaultBU)
		vel.x = g_bfmeDefaultBU;
	animWin->setVel(vel);
	return false;
}
